--
-- Name: a_xnat_eegscandata(integer, integer, character varying, boolean); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.a_xnat_eegscandata(integer, integer, character varying, boolean) RETURNS text
    LANGUAGE plpgsql
    AS $_$
    declare
     current_row RECORD;
     row_ct int4;
    begin
      row_ct := 0;
       --UPDATE LOCAL ROW
      FOR current_row IN SELECT xnat_eegScanData.*, meta.meta_data_id, meta.status AS meta_status FROM xnat_eegScanData LEFT JOIN xnat_eegScanData_meta_data meta ON xnat_eegScanData.eegScanData_info=meta.meta_data_id WHERE  xnat_imagescandata_id=$1
      LOOP
           row_ct := row_ct+1;
           IF (current_row.meta_status!=$3) THEN
         UPDATE xnat_eegScanData_meta_data SET status=$3,activation_date=NOW(),activation_user_xdat_user_id=$2 WHERE meta_data_id=current_row.meta_data_id;
           END IF;
          
        IF ((current_row.xnat_imagescandata_id IS NOT NULL)) THEN
          PERFORM  ae_xnat_imageScanData(current_row.xnat_imagescandata_id, $2,$3,false);
        END IF;
        DECLARE 
        parent_row RECORD; 
        BEGIN 
        FOR parent_row IN SELECT * FROM xnat_eegScanData_channel WHERE channels_channel_xnat_eegScanDa_xnat_imagescandata_id=current_row.xnat_imagescandata_id
        LOOP
          PERFORM  a_xnat_eegScanData_channel( parent_row.xnat_eegscandata_channel_id, $2,$3,false);
        END LOOP;
        END;
        DECLARE 
        parent_row RECORD; 
        BEGIN 
        FOR parent_row IN SELECT * FROM xnat_eegScanData_impedance WHERE softwarefiltersimpedances_imped_xnat_imagescandata_id=current_row.xnat_imagescandata_id
        LOOP
          PERFORM  a_xnat_eegScanData_impedance( parent_row.xnat_eegscandata_impedance_id, $2,$3,false);
        END LOOP;
        END;
      END LOOP;
      IF (row_ct=0) THEN 
          PERFORM  ae_xnat_imageScanData( $1, $2,$3,$4);
          
      END IF;
	
	 RETURN '';
    end;
$_$;


