--
-- Name: activity_entries(character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.activity_entries(dbname character varying DEFAULT 'xnat'::character varying) RETURNS TABLE(username character varying, ip_address character varying, pid integer, application_name text, state text, last_query text, state_change timestamp with time zone, wait_event text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
        SELECT
            a.usename::VARCHAR(255),
            coalesce(client_addr::VARCHAR(255), 'local')::VARCHAR(255),
            a.pid,
            CASE WHEN a.application_name = '' THEN '<empty>' ELSE a.application_name END,
            a.state,
            a.query,
            a.state_change,
            a.wait_event
        FROM
            pg_stat_activity a
        WHERE
            a.datname = dbName;
END
$$;


ALTER FUNCTION public.activity_entries(dbname character varying) OWNER TO xnat;

--
-- Name: activity_summary(character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.activity_summary(dbname character varying DEFAULT 'xnat'::character varying) RETURNS TABLE(total_connections bigint, applications text[], ip_addresses inet[], users character varying[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
        WITH
            activity AS (SELECT * FROM pg_stat_activity WHERE datname = dbName)
        SELECT
                (SELECT count(*) FROM activity),
                (SELECT
                     array_replace(array(SELECT
                                             CASE WHEN application_name = '' THEN '<empty>' ELSE application_name END || ': ' || connection_count
                                         FROM
                                             (SELECT
                                                  application_name,
                                                  count(application_name) AS connection_count
                                              FROM
                                                  activity
                                              GROUP BY
                                                  application_name) connections), '', '<empty>')),
                (SELECT array(SELECT DISTINCT client_addr FROM activity)),
                (SELECT array(SELECT DISTINCT usename::VARCHAR(255) FROM activity));
END
$$;


ALTER FUNCTION public.activity_summary(dbname character varying) OWNER TO xnat;

--
-- Name: adjust_sequences(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.adjust_sequences() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  adjusted_sequences INTEGER = 0;
  current_row        RECORD;
BEGIN
  FOR current_row IN SELECT * FROM get_maladjusted_sequences()
    LOOP
      adjusted_sequences := adjusted_sequences + 1;
      EXECUTE format('SELECT setval(''%s'', %L)', current_row.sequence_name, current_row.max_key_value);
    END LOOP;
  RETURN adjusted_sequences;
END
$$;


ALTER FUNCTION public.adjust_sequences() OWNER TO xnat;

