--
-- Name: class_exists(character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.class_exists(character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
    declare
     current_row RECORD;
    begin
      FOR current_row IN SELECT * FROM pg_catalog.pg_class WHERE  relname=LOWER($1)
     LOOP
          RETURN TRUE;
      END LOOP;

	 RETURN FALSE;
    end;
$_$;


ALTER FUNCTION public.class_exists(character varying) OWNER TO xnat;

--
-- Name: create_class2(character varying, character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.create_class2(character varying, character varying) RETURNS void
    LANGUAGE plpgsql
    AS $_$
    begin
	IF(NOT CLASS_EXISTS($1)) THEN
		EXECUTE $2;
		RETURN;
	END IF;
	RETURN;
    end;
$_$;


ALTER FUNCTION public.create_class2(character varying, character varying) OWNER TO xnat;

--
-- Name: create_function2(character varying, character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.create_function2(character varying, character varying) RETURNS void
    LANGUAGE plpgsql
    AS $_$
    begin
	IF(NOT FUNCTION_EXISTS($1)) THEN
		EXECUTE $2;
		RETURN ;
	END IF;

	RETURN ;
    end;
$_$;


