--

CREATE FUNCTION public.create_schema2(character varying, character varying) RETURNS void
    LANGUAGE plpgsql
    AS $_$
    begin
	IF(NOT SCHEMA_EXISTS($1)) THEN
		EXECUTE $2;
		RETURN ;
	END IF;
	RETURN ;
    end;
$_$;


