-- Name: data_type_fns_find_orphaned_data(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.data_type_fns_find_orphaned_data() RETURNS TABLE(project character varying, id character varying, label character varying, element_name character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY SELECT
                     x.project,
                     x.id,
                     x.label,
                     e.element_name
                 FROM
                     xnat_experimentdata x
                     LEFT JOIN xdat_meta_element e ON x.extension = e.xdat_meta_element_id
                 WHERE NOT data_type_fns_object_exists_in_table(x.id, e.element_name);
END
$$;


