-- Name: data_type_fns_find_orphaned_scans(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.data_type_fns_find_orphaned_scans() RETURNS TABLE(project character varying, label character varying, id character varying, xnat_imagescandata_id integer, modality character varying, type character varying, series_description character varying, element_name character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY SELECT
                     s.project,
                     x.label,
                     s.id,
                     s.xnat_imagescandata_id,
                     s.modality,
                     s.type,
                     s.series_description,
                     e.element_name
                 FROM
                     xnat_imagescandata s
                     LEFT JOIN xdat_meta_element e ON s.extension = e.xdat_meta_element_id
                     LEFT JOIN xnat_imagesessiondata i ON s.image_session_id = i.id
                     LEFT JOIN xnat_experimentdata x ON i.id = x.id
                 WHERE NOT data_type_fns_scan_exists_in_table(s.xnat_imagescandata_id, e.element_name);
END
$$;


