--
-- Name: dependencies_identify(name, name); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.dependencies_identify(pviewname name, pviewschema name DEFAULT 'public'::name) RETURNS TABLE(view_schema character varying, view_name character varying, view_type character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
        SELECT
            obj_schema::VARCHAR,
            obj_name::VARCHAR,
            obj_type::VARCHAR
        FROM
            (WITH
                 RECURSIVE
                 recursive_deps(obj_schema, obj_name, obj_type, depth) AS
                     (SELECT
                          pViewSchema,
                          pViewName,
                          NULL::VARCHAR,
                          0
                      UNION
                      SELECT
                          dep_schema::VARCHAR,
                          dep_name::VARCHAR,
                          dep_type::VARCHAR,
                          recursive_deps.depth + 1
                      FROM
                          (SELECT
                               ref_nsp.nspname ref_schema,
                               ref_cl.relname  ref_name,
                               rwr_cl.relkind  dep_type,
                               rwr_nsp.nspname dep_schema,
                               rwr_cl.relname  dep_name
                           FROM
                               pg_depend dep
                                   JOIN pg_class ref_cl ON dep.refobjid = ref_cl.oid
                                   JOIN pg_namespace ref_nsp ON ref_cl.relnamespace = ref_nsp.oid
                                   JOIN pg_rewrite rwr ON dep.objid = rwr.oid
                                   JOIN pg_class rwr_cl ON rwr.ev_class = rwr_cl.oid
                                   JOIN pg_namespace rwr_nsp ON rwr_cl.relnamespace = rwr_nsp.oid
                           WHERE
                               dep.deptype = 'n' AND
                               dep.classid = 'pg_rewrite'::REGCLASS) deps
                              JOIN recursive_deps ON deps.ref_schema = recursive_deps.obj_schema AND deps.ref_name = recursive_deps.obj_name
                      WHERE
                          deps.ref_schema != deps.dep_schema OR
                          deps.ref_name != deps.dep_name)
             SELECT
                 obj_schema,
                 obj_name,
                 obj_type,
                 depth
             FROM
                 recursive_deps
             WHERE
                 depth > 0) t
        GROUP BY
            obj_schema,
            obj_name,
            obj_type
        ORDER BY
            max(depth) DESC;
END;
$$;


ALTER FUNCTION public.dependencies_identify(pviewname name, pviewschema name) OWNER TO xnat;

--
-- Name: dependencies_restore(name, name); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.dependencies_restore(pviewname name, pviewschema name DEFAULT 'public'::name) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_record RECORD;
    total_records  INTEGER := 0;
BEGIN
    FOR current_record IN
        (SELECT
             ddl_to_run
         FROM
             xdat_search.dependencies_saved_ddl
         WHERE
             view_schema = pViewSchema AND
             view_name = pViewName
         ORDER BY
             id DESC)
        LOOP
            IF current_record.ddl_to_run LIKE 'CREATE %'
            THEN
                total_records := total_records + 1;
            END IF;
            EXECUTE current_record.ddl_to_run;
        END LOOP;
    DELETE
    FROM
        xdat_search.dependencies_saved_ddl
    WHERE
        view_schema = pViewSchema AND
        view_name = pViewName;
    RETURN total_records;
END;
$$;


ALTER FUNCTION public.dependencies_restore(pviewname name, pviewschema name) OWNER TO xnat;

--
-- Name: dependencies_save_and_drop(name, name); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.dependencies_save_and_drop(pviewname name, pviewschema name DEFAULT 'public'::name) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_record RECORD;
    total_records  INTEGER := 0;
BEGIN
    FOR current_record IN
        SELECT view_schema, view_name, view_type FROM dependencies_identify(pViewName, pViewSchema)
        LOOP
            total_records := total_records + 1;
            INSERT INTO xdat_search.dependencies_saved_ddl(view_schema, view_name, ddl_to_run)
            SELECT
                pViewSchema,
                pViewName,
                'COMMENT ON ' ||
                CASE
                    WHEN c.relkind = 'v' THEN 'VIEW'
                    WHEN c.relkind = 'm' THEN 'MATERIALIZED VIEW'
                    ELSE ''
                END
                    || ' ' || n.nspname || '.' || c.relname || ' IS ''' || replace(d.description, '''', '''''') || ''';'
            FROM
                pg_class c
                    JOIN pg_namespace n ON n.oid = c.relnamespace
                    JOIN pg_description d ON d.objoid = c.oid AND d.objsubid = 0
            WHERE
                n.nspname = current_record.view_schema AND
                c.relname = current_record.view_name AND
                d.description IS NOT NULL;

            INSERT INTO xdat_search.dependencies_saved_ddl(view_schema, view_name, ddl_to_run)
            SELECT
                pViewSchema,
                pViewName,
                'COMMENT ON COLUMN ' || n.nspname || '.' || c.relname || '.' || a.attname || ' IS ''' || replace(d.description, '''', '''''') || ''';'
            FROM
                pg_class c
                    JOIN pg_attribute a ON c.oid = a.attrelid
                    JOIN pg_namespace n ON n.oid = c.relnamespace
                    JOIN pg_description d ON d.objoid = c.oid AND d.objsubid = a.attnum
            WHERE
                n.nspname = current_record.view_schema AND
                c.relname = current_record.view_name AND
                d.description IS NOT NULL;

            INSERT INTO xdat_search.dependencies_saved_ddl(view_schema, view_name, ddl_to_run)
            SELECT
                pViewSchema,
                pViewName,
                'GRANT ' || privilege_type || ' ON ' || table_schema || '.' || table_name || ' TO ' || grantee
            FROM
                information_schema.role_table_grants
            WHERE
                table_schema = current_record.view_schema AND
                table_name = current_record.view_name;

            IF current_record.view_type = 'v'
            THEN
                INSERT INTO xdat_search.dependencies_saved_ddl(view_schema, view_name, ddl_to_run)
                SELECT
                    pViewSchema,
                    pViewName,
                    'CREATE VIEW ' || current_record.view_schema || '.' || current_record.view_name || ' AS ' || view_definition
                FROM
                    information_schema.views
                WHERE
                    table_schema = current_record.view_schema AND
                    table_name = current_record.view_name;
            ELSIF current_record.view_type = 'm'
            THEN
                INSERT INTO xdat_search.dependencies_saved_ddl(view_schema, view_name, ddl_to_run)
                SELECT
                    pViewSchema,
                    pViewName,
                    'CREATE MATERIALIZED VIEW ' || current_record.view_schema || '.' || current_record.view_name || ' AS ' || definition
                FROM
                    pg_matviews
                WHERE
                    schemaname = current_record.view_schema AND
                    matviewname = current_record.view_name;
            END IF;

            EXECUTE 'DROP ' ||
                    CASE
                        WHEN current_record.view_type = 'v' THEN 'VIEW'
                        WHEN current_record.view_type = 'm' THEN 'MATERIALIZED VIEW'
                    END
                        || ' ' || current_record.view_schema || '.' || current_record.view_name;

        END LOOP;
    RETURN total_records;
END;
$$;


ALTER FUNCTION public.dependencies_save_and_drop(pviewname name, pviewschema name) OWNER TO xnat;

