CREATE FUNCTION public.function_exists(character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
    declare
     current_row RECORD;
    begin
      FOR current_row IN SELECT * FROM pg_proc WHERE  proname=LOWER($1)
     LOOP
          RETURN TRUE;
      END LOOP;

	 RETURN FALSE;
    end;
$_$;


