--
-- Name: get_accessible_image_sessions(character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.get_accessible_image_sessions(username character varying) RETURNS TABLE(id character varying, label character varying, project character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    has_all_data_access BOOLEAN;
BEGIN
    SELECT has_all_data_access(username) INTO has_all_data_access;

    IF has_all_data_access
    THEN
        RETURN QUERY
            SELECT DISTINCT ON (expts.id)
                expts.id,
                expts.label,
                expts.project
            FROM
                xnat_imageSessionData isd
                    LEFT JOIN xnat_experimentData expts ON isd.id = expts.id;
    ELSE
        RETURN QUERY
            WITH
                perms AS (
                    SELECT
                        a.element_name,
                        m.field,
                        m.field_value
                    FROM
                        xdat_user u
                            LEFT JOIN xdat_user_groupid i ON u.xdat_user_id = i.groups_groupid_xdat_user_xdat_user_id
                            LEFT JOIN xdat_usergroup g ON i.groupid = g.id
                            LEFT JOIN xdat_element_access a ON (xdat_usergroup_id = a.xdat_usergroup_xdat_usergroup_id OR u.xdat_user_id = a.xdat_user_xdat_user_id)
                            LEFT JOIN xdat_field_mapping_set s ON a.xdat_element_access_id = s.permissions_allow_set_xdat_elem_xdat_element_access_id
                            LEFT JOIN xdat_field_mapping m ON s.xdat_field_mapping_set_id = m.xdat_field_mapping_set_xdat_field_mapping_set_id
                    WHERE
                        m.field_value != '*' AND
                        m.read_element = 1 AND
                        u.login IN ('guest', username)),
                expts AS (SELECT * FROM get_all_image_sessions)
            SELECT DISTINCT ON (e.id)
                e.id,
                e.label,
                e.project
            FROM
                perms p
                    INNER JOIN expts e ON left(p.field, strpos(p.field, '/') - 1) = left(e.field, strpos(e.field, '/') - 1) AND p.field_value = e.project;
    END IF;
END
$$;


ALTER FUNCTION public.get_accessible_image_sessions(username character varying) OWNER TO xnat;

--
-- Name: get_experiment_list(character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.get_experiment_list(username character varying, numresults integer DEFAULT 60, numdays integer DEFAULT 60) RETURNS TABLE(id character varying, label character varying, project character varying, date date, status character varying, workflow_status character varying, element_name character varying, type_desc character varying, insert_date timestamp without time zone, activation_date timestamp without time zone, last_modified timestamp without time zone, workflow_date timestamp without time zone, pipeline_name text, action_date timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    idleInterval TIMESTAMP;
BEGIN
    idleInterval := NOW() - make_interval(days := numDays);

    RETURN QUERY
        SELECT *
        FROM
            (SELECT DISTINCT ON (expt.id)
                 expt.id,
                 perm.label,
                 perm.project,
                 expt.date,
                 emd.status,
                 W.workflow_status,
                 xme.element_name,
                 COALESCE(es.code, es.singular, es.element_name)               AS TYPE_DESC,
                 emd.insert_date,
                 emd.activation_date,
                 emd.last_modified,
                 W.workflow_date,
                 W.pipeline_name,
                 COALESCE(W.workflow_date, emd.last_modified, emd.insert_date) AS action_date
             FROM
                 xnat_experimentData expt
                     LEFT JOIN  xdat_meta_element xme ON expt.extension = xme.xdat_meta_element_id
                     LEFT JOIN  xnat_experimentData_meta_data emd ON expt.experimentData_info = emd.meta_data_id
                     LEFT JOIN  xdat_element_security es ON xme.element_name = es.element_name
                     LEFT JOIN  (SELECT W.workflow_id, W.workflow_date, W.pipeline_name, W.workflow_status FROM get_open_workflows(numDays) W) W ON expt.id = W.workflow_id
                     RIGHT JOIN (SELECT S.id, S.label, S.project FROM get_accessible_image_sessions(username) S) perm ON expt.id = perm.id
                     RIGHT JOIN xnat_imageSessionData isd ON perm.id = isd.id
             WHERE
                 emd.status != 'obsolete' AND
                 (emd.insert_date > idleInterval OR emd.activation_date > idleInterval OR emd.last_modified > idleInterval OR W.workflow_date > idleInterval)) SEARCH
        ORDER BY
            SEARCH.action_date DESC
        LIMIT numResults;
END
$$;


ALTER FUNCTION public.get_experiment_list(username character varying, numresults integer, numdays integer) OWNER TO xnat;

--
-- Name: get_maladjusted_sequences(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.get_maladjusted_sequences() RETURNS TABLE(table_name text, column_name text, sequence_name text, max_key_value bigint, next_seq_value bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY SELECT
                 v.table_name,
                 v.column_name,
                 v.sequence_name,
                 v.max_key_value,
                 v.next_seq_value
               FROM
                 get_table_pk_max_and_next_value() v
               WHERE
                 v.max_key_value IS NOT NULL AND
                   v.max_key_value > v.next_seq_value;
END
$$;


ALTER FUNCTION public.get_maladjusted_sequences() OWNER TO xnat;

--
-- Name: get_open_workflows(integer); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.get_open_workflows(numdays integer DEFAULT 60) RETURNS TABLE(workflow_id character varying, workflow_date timestamp without time zone, pipeline_name text, workflow_status character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
        SELECT DISTINCT ON (w.id)
            w.id          AS workflow_id,
            w.launch_time AS workflow_date,
            CASE w.pipeline_name
                WHEN 'Transferred'::TEXT THEN 'Archived'::TEXT
                ELSE CASE xs_lastposition('/'::TEXT, w.pipeline_name::TEXT)
                         WHEN 0 THEN w.pipeline_name
                         ELSE substring(substring(w.pipeline_name::TEXT, xs_lastposition('/'::TEXT, w.pipeline_name::TEXT) + 1), 1, xs_lastposition('.'::TEXT, substring(w.pipeline_name::TEXT, xs_lastposition('/'::TEXT, w.pipeline_name::TEXT) + 1)) - 1)
                     END
            END           AS pipeline_name,
            w.status      AS workflow_status
        FROM
            wrk_workflowdata w
        WHERE
            w.category != 'SIDE_ADMIN' AND
            w.launch_time > NOW() - make_interval(days := numDays) AND
            w.status != 'Failed (Dismissed)' AND
            w.pipeline_name NOT LIKE 'xnat_tools%AutoRun.xml'
        ORDER BY
            w.id,
            w.launch_time DESC;
END
$$;


ALTER FUNCTION public.get_open_workflows(numdays integer) OWNER TO xnat;

--
-- Name: get_sequence_last_value(text, text); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.get_sequence_last_value(sequence_name text, schema_name text DEFAULT 'public'::text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
  last_value BIGINT;
BEGIN
  IF get_server_version() < 10.0
  THEN
    EXECUTE format('SELECT CASE WHEN (start_value >= last_value) THEN start_value WHEN last_value IS NULL THEN 0 ELSE last_value END AS LAST_COUNT from %I', sequence_name) INTO last_value;
  ELSE
    EXECUTE format('SELECT CASE WHEN (start_value >= last_value) THEN start_value WHEN last_value IS NULL THEN 0 ELSE last_value END AS LAST_COUNT FROM pg_sequences WHERE schemaname = %L AND sequencename = %L', schema_name, sequence_name) INTO last_value;
  END IF;
  RETURN last_value;
END
$$;


ALTER FUNCTION public.get_sequence_last_value(sequence_name text, schema_name text) OWNER TO xnat;

--
-- Name: get_sequences_and_last_values(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.get_sequences_and_last_values() RETURNS TABLE(sequence_name text, next_seq_value bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  seq_query VARCHAR(255);
BEGIN
  IF (SELECT get_server_version()) < 10.0
  THEN
    seq_query := 'SELECT c.relname::TEXT AS sequencename, get_sequence_last_value(c.relname) AS last_value FROM pg_class c WHERE c.relkind = ''S''';
  ELSE
    seq_query := 'SELECT sequencename::TEXT, get_sequence_last_value(sequencename) FROM pg_sequences';
  END IF;

  RETURN QUERY EXECUTE seq_query;
END
$$;


ALTER FUNCTION public.get_sequences_and_last_values() OWNER TO xnat;

--
-- Name: get_server_version(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.get_server_version() RETURNS double precision
    LANGUAGE plpgsql
    AS $$
DECLARE
  version FLOAT;
BEGIN
  SELECT
    CAST((split_part(server_version, '.', 1) || '.' || split_part(server_version, '.', 2)) AS FLOAT) FROM (SELECT split_part(setting, ' ', 1) AS server_version FROM pg_settings WHERE name = 'server_version') AS trimmed INTO version;
  RETURN version;
END
$$;


ALTER FUNCTION public.get_server_version() OWNER TO xnat;

--
-- Name: get_table_max_pk_value(text, text); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.get_table_max_pk_value(table_name text, primary_key text) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
  max_value BIGINT;
BEGIN
  EXECUTE format('SELECT max(%I) AS max_value FROM %I', primary_key, table_name) INTO max_value;
  RETURN max_value;
END
$$;


ALTER FUNCTION public.get_table_max_pk_value(table_name text, primary_key text) OWNER TO xnat;

--
-- Name: get_table_pk_max_and_next_value(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.get_table_pk_max_and_next_value() RETURNS TABLE(table_name text, column_name text, sequence_name text, max_key_value bigint, next_seq_value bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN
  RETURN QUERY
    WITH sequence_data AS (SELECT
                             tpkas.table_catalog::TEXT AS table_catalog,
                             tpkas.table_schema::TEXT AS table_schema,
                             tpkas.table_name::TEXT AS table_name,
                             tpkas.column_name::TEXT AS column_name,
                             tpkas.sequence_name::TEXT AS sequence_name
                           FROM
                             table_primary_keys_and_sequences tpkas)
    SELECT
      tpkas.table_name,
      tpkas.column_name,
      tpkas.sequence_name,
      get_table_max_pk_value(tpkas.table_name, tpkas.column_name) AS max_value,
      s.next_seq_value
    FROM
      sequence_data tpkas
        LEFT JOIN get_sequences_and_last_values() s ON tpkas.sequence_name = s.sequence_name;
END
$$;


ALTER FUNCTION public.get_table_pk_max_and_next_value() OWNER TO xnat;

--
-- Name: getnextview(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.getnextview() RETURNS name
    LANGUAGE plpgsql
    AS $$ DECLARE   my_record RECORD;  viewName name; 
BEGIN  FOR my_record IN SELECT c.relname FROM pg_catalog.pg_class AS c LEFT JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace
WHERE     c.relkind IN ('v') AND n.nspname NOT IN ('pg_catalog', 'pg_toast') AND pg_catalog.pg_table_is_visible(c.oid) LIMIT 1
LOOP   viewName := my_record.relname;  END LOOP;  RETURN (viewName); END; $$;


