--
-- Name: has_all_data_access(character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.has_all_data_access(username character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    has_all_data_access BOOLEAN;
BEGIN
    SELECT
        EXISTS(
                SELECT
                    u.login
                FROM
                    xdat_usergroup g
                        LEFT JOIN xdat_user_groupid i ON g.id = i.groupid
                        LEFT JOIN xdat_user u ON i.groups_groupid_xdat_user_xdat_user_id = u.xdat_user_id
                WHERE
                    g.id IN ('ALL_DATA_ACCESS', 'ALL_DATA_ADMIN') AND
                    u.login = username)
    INTO has_all_data_access;
    RETURN has_all_data_access;
END
$$;


ALTER FUNCTION public.has_all_data_access(username character varying) OWNER TO xnat;

