--
-- Name: i_xnat_genericdata(character varying, integer, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.i_xnat_genericdata(character varying, integer, boolean, boolean, boolean) RETURNS text
    LANGUAGE plpgsql
    AS $_$
    declare
     current_row RECORD;
     fullText TEXT;
    begin
      FOR current_row IN SELECT * FROM (SELECT table0.id AS xnat_genericData0, table2.element_name AS xdat_meta_element138, table0.date AS xnat_experimentData2 FROM xnat_genericData xnat_genericData   LEFT JOIN xnat_experimentData table0 ON xnat_genericData.id=table0.id   LEFT JOIN xdat_meta_element table2 ON table0.extension=table2.xdat_meta_element_id) SEARCH  WHERE 
 ( (xnat_genericData0=$1))
      LOOP
         IF (current_row.xdat_meta_element138 IS NULL) THEN 
             fullText:= ie_xnat_genericData( $1, $2,$3,$4,$5);
         ELSE
            --CALL EXTENDER 
            declare
               matches int4:=0;
            begin
            IF (current_row.xdat_meta_element138='xnat:pVisitData') THEN
                fullText:= i_xnat_pVisitData( $1, $2,$3,$4,$5);
                matches:=1;
            END IF;
            IF (current_row.xdat_meta_element138='xnat:abstractProjectAsset') THEN
                fullText:= i_xnat_abstractProjectAsset( $1, $2,$3,$4,$5);
                matches:=1;
            END IF;
                IF (matches=0) THEN
                    fullText:= ie_xnat_genericData( $1, $2,$3,$4,$5);
                END IF;
            end;
         end IF;
      END LOOP;
	
	RETURN fullText;
    end;
$_$;


