                matches:=1;
            END IF;
            IF (current_row.xdat_meta_element33='xnat:resourceCatalog') THEN
                fullText:= i_xnat_resourceCatalog( $1, $2,$3,$4,$5);
                matches:=1;
            END IF;
                IF (matches=0) THEN
