              fullText := fullText || '(' || tempText || ')';
              loop_count := loop_count+1;
        END LOOP;
        END;
        END IF; 
        IF ((current_row.studyProtocol_info IS NOT NULL)) THEN
            fullText := fullText || '(studyprotocol_info:integer)=(' || current_row.studyprotocol_info || ')';
 -- 693
           child_count := child_count+1;
