--
-- Name: project_groups_create_mapping_sets(character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.project_groups_create_mapping_sets(projectid character varying) RETURNS TABLE(xdat_field_mapping_set_id integer, method character varying, xdat_element_access_id integer, element_name character varying, xdat_usergroup_id integer, id character varying, displayname character varying, tag character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT
    INTO
        xdat_field_mapping_set (method, permissions_allow_set_xdat_elem_xdat_element_access_id)
    SELECT
        'OR' AS method,
        a.xdat_element_access_id
    FROM
        xdat_element_access a
        LEFT JOIN xdat_usergroup g ON a.xdat_usergroup_xdat_usergroup_id = g.xdat_usergroup_id
        LEFT JOIN xdat_field_mapping_set s ON a.xdat_element_access_id = s.permissions_allow_set_xdat_elem_xdat_element_access_id
    WHERE
            g.tag = projectId AND
            g.displayname IN ('Owners', 'Members', 'Collaborators') AND
            s.method IS NULL;

    RETURN QUERY
        SELECT
            s.xdat_field_mapping_set_id,
            s.method,
            s.xdat_element_access_id,
            s.element_name,
            s.xdat_usergroup_id,
            s.id,
            s.displayname,
            s.tag
        FROM
            project_groups_get_mapping_sets(projectId) s;
END
$$;


