--

CREATE FUNCTION public.project_groups_get_setting_flip_value(elementname character varying, mismatchedvalue integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF mismatchedValue IS NULL
    THEN
        RETURN NULL;
    ELSEIF mismatchedValue = 1
    THEN
        RETURN elementName || '_element = 0';
    END IF;
    RETURN elementName || '_element = 1';
END
$$;


