-- Name: removeviews(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.removeviews() RETURNS character varying
    LANGUAGE plpgsql
    AS $$ DECLARE  viewName name;  viewCounter int8; 
BEGIN  SELECT INTO viewName getnextview();  SELECT INTO viewCounter viewCount();  WHILE (viewCounter > 0)   LOOP
EXECUTE 'DROP VIEW '|| viewName || ' CASCADE';   RAISE NOTICE 'DROPPED %. % more.',viewName,viewCounter;   SELECT INTO viewName getnextview();
SELECT INTO viewCounter viewCount();  END LOOP;   RETURN ('DONE'); END; $$;


