--
-- Name: stringstosortedtable(character varying[]); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.stringstosortedtable(character varying[]) RETURNS SETOF public.sortedstrings
    LANGUAGE plpgsql
    AS $_$DECLARE  
ss sortedstrings%ROWTYPE; 
i int4;  
BEGIN  
i :=1 ;
WHILE ($1[i] IS NOT NULL) 
LOOP   
		FOR ss IN 
			SELECT * FROM getSortedString($1[i],i) 
		LOOP
			RAISE NOTICE 'SORTED STRING: %,%',ss.strings,ss.sort_order;
			RETURN NEXT ss;
		END LOOP;
		i:=i+1; 
	END LOOP; 
	RETURN; 
END;$_$;


