--
-- Name: update_ls_arc_archivespecification(integer, integer); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.update_ls_arc_archivespecification(integer, integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
    declare
     current_row RECORD;
    begin

       --DELETE CACHE
      declare
        current_cache RECORD;
      BEGIN
        FOR current_cache IN SELECT id FROM xs_item_cache WHERE elementname='arc:ArchiveSpecification' AND ids=CAST($1 AS text)
        LOOP
         DELETE FROM xs_item_cache WHERE id=current_cache.id;
        END LOOP;
      END;

       --UPDATE LOCAL ROW
      FOR current_row IN SELECT arc_ArchiveSpecification.*, meta.meta_data_id FROM arc_ArchiveSpecification LEFT JOIN arc_ArchiveSpecification_meta_data meta ON arc_ArchiveSpecification.ArchiveSpecification_info=meta.meta_data_id WHERE  arc_archivespecification_id=$1
      LOOP
         UPDATE arc_ArchiveSpecification_meta_data SET last_modified=NOW(), modified=1 WHERE meta_data_id=current_row.meta_data_id;
      END LOOP;

      --UPDATE PARENTS;
	
	RETURN 'DONE';
    end;
$_$;


ALTER FUNCTION public.update_ls_arc_archivespecification(integer, integer) OWNER TO xnat;

