CREATE FUNCTION public.update_ls_xnat_iosessiondata(character varying, integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
    declare
     current_row RECORD;
    begin

       --DELETE CACHE
      declare
        current_cache RECORD;
      BEGIN
        FOR current_cache IN SELECT id FROM xs_item_cache WHERE elementname='xnat:ioSessionData' AND ids=CAST($1 AS text)
        LOOP
         DELETE FROM xs_item_cache WHERE id=current_cache.id;
        END LOOP;
      END;

       --UPDATE LOCAL ROW
      FOR current_row IN SELECT xnat_ioSessionData.*, meta.meta_data_id FROM xnat_ioSessionData LEFT JOIN xnat_ioSessionData_meta_data meta ON xnat_ioSessionData.ioSessionData_info=meta.meta_data_id WHERE  id=$1
      LOOP
         UPDATE xnat_ioSessionData_meta_data SET last_modified=NOW(), modified=1 WHERE meta_data_id=current_row.meta_data_id;
      END LOOP;

      --UPDATE PARENTS;

        -- PROCESS EXTENSION
        PERFORM update_ls_ext_xnat_imageSessionData( $1, $2);
	
	RETURN 'DONE';
    end;
$_$;


