--
-- Name: update_ls_xnat_subjectdata(character varying, integer); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.update_ls_xnat_subjectdata(character varying, integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
    declare
     current_row RECORD;
    begin

       --DELETE CACHE
      declare
        current_cache RECORD;
      BEGIN
        FOR current_cache IN SELECT id FROM xs_item_cache WHERE elementname='xnat:subjectData' AND ids=CAST($1 AS text)
        LOOP
         DELETE FROM xs_item_cache WHERE id=current_cache.id;
        END LOOP;
      END;

       --UPDATE LOCAL ROW
      FOR current_row IN SELECT xnat_subjectData.*, meta.meta_data_id FROM xnat_subjectData LEFT JOIN xnat_subjectData_meta_data meta ON xnat_subjectData.subjectData_info=meta.meta_data_id WHERE  id=$1
      LOOP
         UPDATE xnat_subjectData_meta_data SET last_modified=NOW(), modified=1 WHERE meta_data_id=current_row.meta_data_id;
      END LOOP;

      --UPDATE PARENTS;

        --PROCESS MAPPING TABLE RELATION xnat:abstractProjectAsset/subjects/subject
        DECLARE 
        mapping_row RECORD; 
        BEGIN 
        FOR mapping_row IN SELECT * FROM xnat_projectAsset_subjectData WHERE  xnat_subjectData_id=current_row.id
           LOOP 
               PERFORM update_ls_xnat_abstractProjectAsset( mapping_row.xnat_abstractProjectAsset_id, $2);
           END LOOP; 
        END; 
	
	RETURN 'DONE';
    end;
$_$;


