--
-- Name: viewcount(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.viewcount() RETURNS bigint
    LANGUAGE plpgsql
    AS $$ DECLARE   my_record RECORD;  counter int8;
BEGIN  FOR my_record IN SELECT * FROM (SELECT COUNT (c.relname) AS view_count FROM pg_catalog.pg_class AS c 
LEFT JOIN pg_catalog.pg_namespace AS n ON n.oid = c.relnamespace WHERE     c.relkind IN ('v') AND n.nspname 
NOT IN ('pg_catalog', 'pg_toast') AND pg_catalog.pg_table_is_visible(c.oid) LIMIT 1) AS COUNT_TABLE  LOOP   counter := my_record.view_count;  
END LOOP;  RETURN (counter); END; $$;


ALTER FUNCTION public.viewcount() OWNER TO xnat;

--
-- Name: xdat_search_create(character varying, character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.xdat_search_create(character varying, character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
    declare
        search_query_name alias for $1;
        search_query alias for $2;
	entry xdat_searches%ROWTYPE;
    begin
	SELECT * INTO entry FROM xdat_searches WHERE search_name = search_query_name;

	    IF FOUND THEN
		RAISE NOTICE 'Search Table % exists.',
		  search_query_name;
		UPDATE xdat_searches SET last_access=NOW() WHERE search_name = search_query_name;
	    ELSE
		RAISE NOTICE 'Creating Search Table %.',
		  search_query_name;
		EXECUTE 'CREATE TABLE ' || search_query_name || ' AS ' || search_query;
		INSERT INTO xdat_searches (search_name) VALUES (search_query_name);
     EXECUTE 'GRANT ALL ON TABLE ' || search_query_name || ' TO public';
	    END IF;

	PERFORM xdat_search_drop_unused();

	RETURN 'DONE';
    end;
$_$;


ALTER FUNCTION public.xdat_search_create(character varying, character varying) OWNER TO xnat;

--
-- Name: xdat_search_create(character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.xdat_search_create(character varying, character varying, character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
    declare
        search_query_name alias for $1;
        search_query alias for $2;
        search_owner alias for $3;
	entry xdat_searches%ROWTYPE;
    begin
	SELECT * INTO entry FROM xdat_searches WHERE search_name = search_query_name;

	    IF FOUND THEN
		RAISE NOTICE 'Search Table % exists.',
		  search_query_name;
		UPDATE xdat_searches SET last_access=NOW() WHERE search_name = search_query_name;
	    ELSE
		RAISE NOTICE 'Creating Search Table %.',
		  search_query_name;
		EXECUTE 'CREATE TABLE ' || search_query_name || ' AS ' || search_query;
		INSERT INTO xdat_searches (search_name,owner) VALUES (search_query_name,search_owner);
	    END IF;

	PERFORM xdat_search_drop_unused(search_owner);

	RETURN 'DONE';
    end;
$_$;


ALTER FUNCTION public.xdat_search_create(character varying, character varying, character varying) OWNER TO xnat;

--
-- Name: xdat_search_drop(character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.xdat_search_drop(character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
    declare
        search_query_name alias for $1;
    begin
	EXECUTE 'DROP TABLE ' || search_query_name;
	DELETE FROM xdat_searches WHERE search_name = search_query_name;
	
	RETURN 'DONE';
    end;
$_$;


ALTER FUNCTION public.xdat_search_drop(character varying) OWNER TO xnat;

--
-- Name: xdat_search_drop_unused(); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.xdat_search_drop_unused() RETURNS character varying
    LANGUAGE plpgsql
    AS $$
    declare
	entry xdat_searches%ROWTYPE;
    begin
	FOR entry IN SELECT * FROM xdat_searches WHERE last_access + INTERVAL '1 hour' / int '2' < NOW()
	LOOP
		PERFORM xdat_search_drop(entry.search_name);

		RAISE NOTICE 'Dropped Expired Search Table %. (Last Access: %)',
		  entry.search_name,entry.last_access;
	END LOOP;

	RETURN 'DONE';
    end;
$$;


ALTER FUNCTION public.xdat_search_drop_unused() OWNER TO xnat;

--
-- Name: xdat_search_drop_unused(character varying); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.xdat_search_drop_unused(character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$
    declare
	entry xdat_searches%ROWTYPE;
        search_owner alias for $1;
    begin
	FOR entry IN SELECT * FROM xdat_searches WHERE owner=search_owner AND last_access + INTERVAL '1 hour' / int '2' < NOW()
	LOOP
		PERFORM xdat_search_drop(entry.search_name);

		RAISE NOTICE 'Dropped Expired Search Table %. (Last Access: %)',
		  entry.search_name,entry.last_access;
	END LOOP;

	RETURN 'DONE';
    end;
$_$;


ALTER FUNCTION public.xdat_search_drop_unused(character varying) OWNER TO xnat;

--
-- Name: xs_concat(text, text); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.xs_concat(text, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
    DECLARE
       t text;
    begin
       IF(character_length($1) > 0) THEN
          t = $1 ||', '|| $2;
       ELSE
          t = $2;
       END IF;
       RETURN t;
    END;
$_$;


ALTER FUNCTION public.xs_concat(text, text) OWNER TO xnat;

--
-- Name: xs_lastposition(text, text); Type: FUNCTION; Schema: public; Owner: xnat
--

CREATE FUNCTION public.xs_lastposition(text, text) RETURNS integer
    LANGUAGE plpgsql
    AS $_$     DECLARE        t text;        i int4:=0;     begin        t = $2;        WHILE(POSITION($1 in t)!=0) LOOP             i = i + POSITION($1 in t);             t = substring(t from (POSITION($1 in t) + 1));        END LOOP;        RETURN i;     END; $_$;


ALTER FUNCTION public.xs_lastposition(text, text) OWNER TO xnat;

