--
-- Name: ct_scan_count_agg; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.ct_scan_count_agg AS
 SELECT _types.image_session_id,
    btrim(public.xs_a_concat((_types.type_count || ', '::text)), ', '::text) AS type_count
   FROM ( SELECT xnat_imagescandata.image_session_id,
            ((((xnat_imagescandata.type)::text || '('::text) || count(xnat_imagescandata.id)) || ')'::text) AS type_count
           FROM public.xnat_imagescandata
          GROUP BY xnat_imagescandata.image_session_id, xnat_imagescandata.type
          ORDER BY xnat_imagescandata.image_session_id, xnat_imagescandata.type) _types
  GROUP BY _types.image_session_id;


ALTER TABLE public.ct_scan_count_agg OWNER TO xnat;

--
-- Name: data_type_views_default_access_permissions; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.data_type_views_default_access_permissions AS
 SELECT groupnames.groupnameorid,
    groupnames.is_source,
    groupnames.create_element,
    groupnames.read_element,
    groupnames.edit_element,
    groupnames.delete_element,
    groupnames.active_element
   FROM ( VALUES ('Owners'::text,true,true,true,true,true,true), ('Owners'::text,false,false,true,false,false,true), ('Members'::text,true,true,true,true,false,true), ('Members'::text,false,false,true,false,false,true), ('Collaborators'::text,true,false,true,false,false,true), ('Collaborators'::text,false,false,true,false,false,true), ('ALL_DATA_ADMIN'::text,true,true,true,true,true,true), ('ALL_DATA_ADMIN'::text,false,true,true,true,true,true), ('ALL_DATA_ACCESS'::text,true,false,true,false,false,true), ('ALL_DATA_ACCESS'::text,false,false,true,false,false,true)) groupnames(groupnameorid, is_source, create_element, read_element, edit_element, delete_element, active_element);


