--
-- Name: data_type_views_element_access; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.data_type_views_element_access AS
 SELECT COALESCE(g.id, (('user:'::text || (u.login)::text))::character varying) AS entity,
    a.element_name,
    m.field_value,
    m.field,
    m.active_element,
    m.read_element,
    m.edit_element,
    m.create_element,
    m.delete_element,
    m.comparison_type,
    s.method,
    a.xdat_element_access_id,
    s.xdat_field_mapping_set_id,
    m.xdat_field_mapping_id
   FROM ((((public.xdat_element_access a
     LEFT JOIN public.xdat_user u ON ((a.xdat_user_xdat_user_id = u.xdat_user_id)))
     LEFT JOIN public.xdat_usergroup g ON ((a.xdat_usergroup_xdat_usergroup_id = g.xdat_usergroup_id)))
     LEFT JOIN public.xdat_field_mapping_set s ON ((a.xdat_element_access_id = s.permissions_allow_set_xdat_elem_xdat_element_access_id)))
     LEFT JOIN public.xdat_field_mapping m ON ((s.xdat_field_mapping_set_id = m.xdat_field_mapping_set_xdat_field_mapping_set_id)));


