--
-- Name: data_type_views_experiments_without_data_type; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.data_type_views_experiments_without_data_type AS
 SELECT DISTINCT e.id AS experiment_id,
    w.data_type,
    xme.xdat_meta_element_id
   FROM (((public.xnat_experimentdata e
     LEFT JOIN public.xdat_meta_element m ON ((e.extension = m.xdat_meta_element_id)))
     LEFT JOIN public.wrk_workflowdata w ON (((e.id)::text = (w.id)::text)))
     LEFT JOIN public.xdat_meta_element xme ON (((w.data_type)::text = (xme.element_name)::text)))
  WHERE (m.element_name IS NULL)
