--
-- Name: data_type_views_missing_or_misconfigured_permissions; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.data_type_views_missing_or_misconfigured_permissions AS
 WITH existing_data_access AS (
         SELECT (((g.id)::text || ':'::text) || (m.field)::text) AS key,
            g.id AS group_id,
            a.element_name,
            m.field,
            m.field_value,
            (m.read_element)::boolean AS read_element,
            (m.edit_element)::boolean AS edit_element,
            (m.create_element)::boolean AS create_element,
            (m.delete_element)::boolean AS delete_element,
            (m.active_element)::boolean AS active_element
           FROM (((public.xdat_usergroup g
             LEFT JOIN public.xdat_element_access a ON ((g.xdat_usergroup_id = a.xdat_usergroup_xdat_usergroup_id)))
             LEFT JOIN public.xdat_field_mapping_set s ON ((a.xdat_element_access_id = s.permissions_allow_set_xdat_elem_xdat_element_access_id)))
             LEFT JOIN public.xdat_field_mapping m ON ((s.xdat_field_mapping_set_id = m.xdat_field_mapping_set_xdat_field_mapping_set_id)))
          WHERE ((a.element_name)::text <> 'xnat:projectData'::text)
        ), all_groups AS (
         SELECT g.id,
            g.displayname
           FROM (public.xdat_usergroup g
             LEFT JOIN public.xnat_projectdata p ON (((g.tag)::text = (p.id)::text)))
          WHERE (((p.id IS NOT NULL) AND ((g.displayname)::text = ANY ((ARRAY['Owners'::character varying, 'Members'::character varying, 'Collaborators'::character varying])::text[]))) OR ((g.id)::text = ANY ((ARRAY['ALL_DATA_ADMIN'::character varying, 'ALL_DATA_ACCESS'::character varying])::text[])))
        ), all_secured_types AS (
         SELECT xdat_element_security.element_name
           FROM public.xdat_element_security
          WHERE ((xdat_element_security.secure = 1) AND ((xdat_element_security.element_name)::text <> 'xnat:projectData'::text))
        ), all_group_elements AS (
         SELECT g.id AS group_id,
            g.displayname,
            t.element_name
           FROM all_groups g,
            all_secured_types t
        ), required_data_access AS (
         SELECT ((((all_group_elements.group_id)::text || ':'::text) || (all_group_elements.element_name)::text) || '/project'::text) AS key,
            all_group_elements.group_id,
            all_group_elements.displayname,
            all_group_elements.element_name,
            ((all_group_elements.element_name)::text || '/project'::text) AS field
           FROM all_group_elements
        UNION
         SELECT ((((all_group_elements.group_id)::text || ':'::text) || (all_group_elements.element_name)::text) || '/sharing/share/project'::text) AS key,
            all_group_elements.group_id,
            all_group_elements.displayname,
            all_group_elements.element_name,
            ((all_group_elements.element_name)::text || '/sharing/share/project'::text) AS field
           FROM all_group_elements
        ), unified AS (
         SELECT r.key AS required_key,
            r.group_id AS required_group_id,
            r.displayname AS required_displayname,
            r.element_name AS required_element_name,
            r.field AS required_field,
                CASE
                    WHEN (r.field ~~ '%/sharing/share/project'::text) THEN false
                    ELSE true
                END AS is_source,
            e.key AS existing_key,
            e.group_id AS existing_group_id,
            e.element_name AS existing_element_name,
            e.field AS existing_field,
            e.field_value AS existing_field_value,
            e.read_element,
            e.edit_element,
            e.create_element,
            e.delete_element,
            e.active_element
           FROM (required_data_access r
             LEFT JOIN existing_data_access e ON ((r.key = e.key)))
        ), unified_permissions AS (
         SELECT u.required_key,
            u.required_group_id,
            u.required_displayname,
            u.required_element_name,
            u.required_field,
            u.is_source,
            u.existing_key,
            u.existing_group_id,
            u.existing_element_name,
            u.existing_field,
            u.existing_field_value,
            u.read_element,
            u.edit_element,
            u.create_element,
            u.delete_element,
            u.active_element,
            p.read_element AS default_read,
            p.edit_element AS default_edit,
            p.create_element AS default_create,
            p.delete_element AS default_delete,
            p.active_element AS default_active
           FROM (unified u
             LEFT JOIN public.data_type_views_default_access_permissions p ON ((((p.groupnameorid = (u.required_group_id)::text) OR (p.groupnameorid = (u.required_displayname)::text)) AND (p.is_source = u.is_source))))
        )
 SELECT unified_permissions.required_key,
    unified_permissions.required_group_id,
    unified_permissions.required_displayname,
    unified_permissions.required_element_name,
    unified_permissions.required_field,
    unified_permissions.is_source,
    unified_permissions.existing_key,
    unified_permissions.existing_group_id,
    unified_permissions.existing_element_name,
    unified_permissions.existing_field,
    unified_permissions.existing_field_value,
    unified_permissions.read_element,
    unified_permissions.edit_element,
    unified_permissions.create_element,
    unified_permissions.delete_element,
    unified_permissions.active_element,
    unified_permissions.default_read,
    unified_permissions.default_edit,
    unified_permissions.default_create,
    unified_permissions.default_delete,
    unified_permissions.default_active
   FROM unified_permissions
  WHERE ((unified_permissions.existing_key IS NULL) OR ((unified_permissions.existing_key IS NOT NULL) AND ((unified_permissions.create_element <> unified_permissions.default_create) OR (unified_permissions.read_element <> unified_permissions.default_read) OR (unified_permissions.edit_element <> unified_permissions.default_edit) OR (unified_permissions.delete_element <> unified_permissions.default_delete) OR (unified_permissions.active_element <> unified_permissions.default_active))));


ALTER TABLE public.data_type_views_missing_or_misconfigured_permissions OWNER TO xnat;

