CREATE VIEW public.xnat_a_scidresearchdata_projects AS
 SELECT expt.id,
    ((('<'::text || (expt.project)::text) || '>'::text) || public.xs_a_concat(((',<'::text || (shared.project)::text) || '>'::text))) AS projects
   FROM ((public.xnat_experimentdata expt
     LEFT JOIN public.xnat_experimentdata_share shared ON (((expt.id)::text = (shared.sharing_share_xnat_experimentda_id)::text)))
     LEFT JOIN public.xdat_meta_element xme ON ((expt.extension = xme.xdat_meta_element_id)))
  WHERE ((xme.element_name)::text = 'xnat_a:scidResearchData'::text)
  GROUP BY expt.id, expt.project;


