--
-- Name: dti_count; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.dti_count AS
 SELECT xnat_imagescandata.image_session_id,
    count(*) AS dti_count
   FROM public.xnat_imagescandata
  WHERE (((xnat_imagescandata.series_description)::text ~~ '%DTI%'::text) OR ((xnat_imagescandata.type)::text ~~ '%DTI%'::text))
  GROUP BY xnat_imagescandata.image_session_id;


