--
-- Name: mr_projects; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.mr_projects AS
 SELECT expt.id,
    ((('<'::text || (expt.project)::text) || '>'::text) || public.xs_a_concat(((',<'::text || (shared.project)::text) || '>'::text))) AS projects
   FROM ((public.xnat_experimentdata expt
     LEFT JOIN public.xnat_experimentdata_share shared ON (((expt.id)::text = (shared.sharing_share_xnat_experimentda_id)::text)))
     LEFT JOIN public.xdat_meta_element xme ON ((expt.extension = xme.xdat_meta_element_id)))
  WHERE ((xme.element_name)::text = 'xnat:mrSessionData'::text)
  GROUP BY expt.id, expt.project;


ALTER TABLE public.mr_projects OWNER TO xnat;

--
-- Name: mr_scan_count_agg; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.mr_scan_count_agg AS
 SELECT _types.image_session_id,
    btrim(public.xs_a_concat((_types.type_count || ', '::text)), ', '::text) AS type_count
   FROM ( SELECT xnat_imagescandata.image_session_id,
            ((((xnat_imagescandata.type)::text || '('::text) || count(xnat_imagescandata.id)) || ')'::text) AS type_count
           FROM public.xnat_imagescandata
          GROUP BY xnat_imagescandata.image_session_id, xnat_imagescandata.type
          ORDER BY xnat_imagescandata.image_session_id, xnat_imagescandata.type) _types
  GROUP BY _types.image_session_id;


ALTER TABLE public.mr_scan_count_agg OWNER TO xnat;

--
-- Name: ordered_workflows; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.ordered_workflows AS
 SELECT wrk_workflowdata.id,
    wrk_workflowdata.status,
    wrk_workflowdata.wrk_workflowdata_id,
        CASE wrk_workflowdata.pipeline_name
            WHEN 'Transfer'::text THEN 'Archive'::text
            ELSE
            CASE public.xs_lastposition('/'::text, (wrk_workflowdata.pipeline_name)::text)
                WHEN 0 THEN (wrk_workflowdata.pipeline_name)::text
                ELSE "substring"("substring"((wrk_workflowdata.pipeline_name)::text, (public.xs_lastposition('/'::text, (wrk_workflowdata.pipeline_name)::text) + 1)), 1, (public.xs_lastposition('.'::text, "substring"((wrk_workflowdata.pipeline_name)::text, (public.xs_lastposition('/'::text, (wrk_workflowdata.pipeline_name)::text) + 1))) - 1))
            END
        END AS pipeline_name
   FROM (public.wrk_workflowdata
     RIGHT JOIN ( SELECT wrk_workflowdata_1.id,
            max(wrk_workflowdata_1.launch_time) AS launch_time
           FROM public.wrk_workflowdata wrk_workflowdata_1
          GROUP BY wrk_workflowdata_1.id) wrk_max ON ((((wrk_workflowdata.id)::text = (wrk_max.id)::text) AND (wrk_workflowdata.launch_time = wrk_max.launch_time))));


ALTER TABLE public.ordered_workflows OWNER TO xnat;

--
-- Name: subject_label; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.subject_label AS
