--
-- Name: project_access; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.project_access AS
 SELECT proj.id,
        CASE
            WHEN ((project_read.project_read = 1) AND (subject_read.subject_read = 1)) THEN 'public'::text
            WHEN (project_read.project_read = 1) THEN 'protected'::text
            ELSE 'private'::text
        END AS accessibility
   FROM ((public.xnat_projectdata proj
     LEFT JOIN ( SELECT fm.field_value,
            fm.read_element AS project_read
           FROM (((public.xdat_element_access ea
             LEFT JOIN public.xdat_field_mapping_set fms ON ((ea.xdat_element_access_id = fms.permissions_allow_set_xdat_elem_xdat_element_access_id)))
             LEFT JOIN public.xdat_user u ON ((ea.xdat_user_xdat_user_id = u.xdat_user_id)))
             LEFT JOIN public.xdat_field_mapping fm ON ((fms.xdat_field_mapping_set_id = fm.xdat_field_mapping_set_xdat_field_mapping_set_id)))
          WHERE (((u.login)::text = 'guest'::text) AND ((ea.element_name)::text = 'xnat:projectData'::text))) project_read ON (((proj.id)::text = (project_read.field_value)::text)))
     LEFT JOIN ( SELECT fm.field_value,
            fm.read_element AS subject_read
           FROM (((public.xdat_element_access ea
             LEFT JOIN public.xdat_field_mapping_set fms ON ((ea.xdat_element_access_id = fms.permissions_allow_set_xdat_elem_xdat_element_access_id)))
             LEFT JOIN public.xdat_user u ON ((ea.xdat_user_xdat_user_id = u.xdat_user_id)))
             LEFT JOIN public.xdat_field_mapping fm ON ((fms.xdat_field_mapping_set_id = fm.xdat_field_mapping_set_xdat_field_mapping_set_id)))
          WHERE (((u.login)::text = 'guest'::text) AND ((fm.field)::text = 'xnat:subjectData/project'::text))) subject_read ON (((proj.id)::text = (subject_read.field_value)::text)));


