--
-- Name: proj_expt_counts; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.proj_expt_counts AS
 SELECT "grouping".project,
    "grouping".element_name,
    count("grouping".id) AS proj_expt_count
   FROM ( SELECT expt.project,
            expt.id,
            xme.element_name
           FROM (public.xnat_experimentdata expt
             LEFT JOIN public.xdat_meta_element xme ON ((expt.extension = xme.xdat_meta_element_id)))
        UNION
         SELECT ep.project,
            ep.label,
            xme.element_name
           FROM ((public.xnat_experimentdata_share ep
             LEFT JOIN public.xnat_experimentdata expt ON (((ep.sharing_share_xnat_experimentda_id)::text = (expt.id)::text)))
             LEFT JOIN public.xdat_meta_element xme ON ((expt.extension = xme.xdat_meta_element_id)))) "grouping"
  GROUP BY "grouping".project, "grouping".element_name;


ALTER TABLE public.proj_expt_counts OWNER TO xnat;

--
-- Name: project_groups_find_irregular_settings; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.project_groups_find_irregular_settings AS
 SELECT mismatched.tag,
    mismatched.id,
    mismatched.xdat_field_mapping_id,
    mismatched.field,
    concat_ws(', '::text, mismatched.mismatched_read, mismatched.mismatched_edit, mismatched.mismatched_create, mismatched.mismatched_delete, mismatched.mismatched_active) AS mismatched_values,
    mismatched.mismatched_read_value,
    mismatched.mismatched_edit_value,
    mismatched.mismatched_create_value,
    mismatched.mismatched_delete_value,
    mismatched.mismatched_active_value
   FROM ( WITH secured_elements AS (
                 SELECT e.element_name
                   FROM public.xdat_element_security e
                  WHERE (e.secure = 1)
                ), project_ids AS (
                 SELECT xnat_projectdata.id
                   FROM public.xnat_projectdata
                ), default_perms AS (
                 SELECT default_perms.scope,
                    default_perms.display_name,
                    default_perms.read_element,
                    default_perms.edit_element,
                    default_perms.create_element,
                    default_perms.delete_element,
                    default_perms.active_element
                   FROM ( VALUES ('project'::text,'Owners'::text,1,1,1,1,1), ('project'::text,'Members'::text,1,0,0,0,0), ('project'::text,'Collaborators'::text,1,0,0,0,0), ('data'::text,'Owners'::text,1,1,1,1,1), ('data'::text,'Members'::text,1,1,1,0,1), ('data'::text,'Collaborators'::text,1,0,0,0,1), ('shared'::text,'Owners'::text,1,0,0,0,1), ('shared'::text,'Members'::text,1,0,0,0,1), ('shared'::text,'Collaborators'::text,1,0,0,0,1)) default_perms(scope, display_name, read_element, edit_element, create_element, delete_element, active_element)
                )
         SELECT g.tag,
            g.id,
            m.xdat_field_mapping_id,
            m.field,
                CASE
                    WHEN (m.read_element <> p.read_element) THEN m.read_element
                    ELSE NULL::integer
                END AS mismatched_read_value,
                CASE
                    WHEN (m.edit_element <> p.edit_element) THEN m.edit_element
                    ELSE NULL::integer
                END AS mismatched_edit_value,
                CASE
                    WHEN (m.create_element <> p.create_element) THEN m.create_element
                    ELSE NULL::integer
                END AS mismatched_create_value,
                CASE
                    WHEN (m.delete_element <> p.delete_element) THEN m.delete_element
                    ELSE NULL::integer
                END AS mismatched_delete_value,
                CASE
                    WHEN (m.active_element <> p.active_element) THEN m.active_element
                    ELSE NULL::integer
                END AS mismatched_active_value,
                CASE
                    WHEN (m.read_element <> p.read_element) THEN 'read'::text
                    ELSE NULL::text
                END AS mismatched_read,
                CASE
                    WHEN (m.edit_element <> p.edit_element) THEN 'edit'::text
                    ELSE NULL::text
                END AS mismatched_edit,
                CASE
                    WHEN (m.create_element <> p.create_element) THEN 'create'::text
                    ELSE NULL::text
                END AS mismatched_create,
                CASE
                    WHEN (m.delete_element <> p.delete_element) THEN 'delete'::text
                    ELSE NULL::text
                END AS mismatched_delete,
                CASE
                    WHEN (m.active_element <> p.active_element) THEN 'active'::text
                    ELSE NULL::text
                END AS mismatched_active
           FROM ((((public.xdat_field_mapping m
             LEFT JOIN public.xdat_field_mapping_set s ON ((m.xdat_field_mapping_set_xdat_field_mapping_set_id = s.xdat_field_mapping_set_id)))
             LEFT JOIN public.xdat_element_access a ON ((s.permissions_allow_set_xdat_elem_xdat_element_access_id = a.xdat_element_access_id)))
             LEFT JOIN public.xdat_usergroup g ON ((a.xdat_usergroup_xdat_usergroup_id = g.xdat_usergroup_id)))
             LEFT JOIN default_perms p ON ((((g.displayname)::text = p.display_name) AND (p.scope = 'project'::text))))
          WHERE (((g.displayname)::text = ANY ((ARRAY['Owners'::character varying, 'Members'::character varying, 'Collaborators'::character varying])::text[])) AND ((g.tag)::text IN ( SELECT project_ids.id
                   FROM project_ids)) AND ((m.field)::text = 'xnat:projectData/ID'::text) AND ((m.read_element <> p.read_element) OR (m.edit_element <> p.edit_element) OR (m.create_element <> p.create_element) OR (m.delete_element <> p.delete_element) OR (m.active_element <> p.active_element)))
        UNION
         SELECT g.tag,
            g.id,
            m.xdat_field_mapping_id,
            m.field,
                CASE
                    WHEN (m.read_element <> p.read_element) THEN m.read_element
                    ELSE NULL::integer
                END AS mismatched_read_value,
                CASE
                    WHEN (m.edit_element <> p.edit_element) THEN m.edit_element
                    ELSE NULL::integer
                END AS mismatched_edit_value,
                CASE
                    WHEN (m.create_element <> p.create_element) THEN m.create_element
                    ELSE NULL::integer
                END AS mismatched_create_value,
                CASE
                    WHEN (m.delete_element <> p.delete_element) THEN m.delete_element
                    ELSE NULL::integer
                END AS mismatched_delete_value,
                CASE
                    WHEN (m.active_element <> p.active_element) THEN m.active_element
                    ELSE NULL::integer
                END AS mismatched_active_value,
                CASE
                    WHEN (m.read_element <> p.read_element) THEN 'read'::text
                    ELSE NULL::text
                END AS mismatched_read,
                CASE
                    WHEN (m.edit_element <> p.edit_element) THEN 'edit'::text
                    ELSE NULL::text
                END AS mismatched_edit,
                CASE
                    WHEN (m.create_element <> p.create_element) THEN 'create'::text
                    ELSE NULL::text
                END AS mismatched_create,
                CASE
                    WHEN (m.delete_element <> p.delete_element) THEN 'delete'::text
                    ELSE NULL::text
                END AS mismatched_delete,
                CASE
                    WHEN (m.active_element <> p.active_element) THEN 'active'::text
                    ELSE NULL::text
                END AS mismatched_active
           FROM ((((public.xdat_field_mapping m
             LEFT JOIN public.xdat_field_mapping_set s ON ((m.xdat_field_mapping_set_xdat_field_mapping_set_id = s.xdat_field_mapping_set_id)))
             LEFT JOIN public.xdat_element_access a ON ((s.permissions_allow_set_xdat_elem_xdat_element_access_id = a.xdat_element_access_id)))
             LEFT JOIN public.xdat_usergroup g ON ((a.xdat_usergroup_xdat_usergroup_id = g.xdat_usergroup_id)))
             LEFT JOIN default_perms p ON ((((g.displayname)::text = p.display_name) AND (p.scope = 'data'::text))))
          WHERE (((g.displayname)::text = ANY ((ARRAY['Owners'::character varying, 'Members'::character varying, 'Collaborators'::character varying])::text[])) AND ((g.tag)::text IN ( SELECT project_ids.id
                   FROM project_ids)) AND ((m.field)::text <> 'xnat:projectData/ID'::text) AND ((m.field)::text !~~ '%/sharing/share/project'::text) AND ((m.field_value)::text <> '*'::text) AND ((m.read_element <> p.read_element) OR (m.edit_element <> p.edit_element) OR (m.create_element <> p.create_element) OR (m.delete_element <> p.delete_element) OR (m.active_element <> p.active_element)))
        UNION
         SELECT g.tag,
            g.id,
            m.xdat_field_mapping_id,
            m.field,
                CASE
                    WHEN (m.read_element <> p.read_element) THEN m.read_element
                    ELSE NULL::integer
                END AS mismatched_read_value,
                CASE
                    WHEN (m.edit_element <> p.edit_element) THEN m.edit_element
                    ELSE NULL::integer
                END AS mismatched_edit_value,
                CASE
                    WHEN (m.create_element <> p.create_element) THEN m.create_element
                    ELSE NULL::integer
                END AS mismatched_create_value,
                CASE
                    WHEN (m.delete_element <> p.delete_element) THEN m.delete_element
                    ELSE NULL::integer
                END AS mismatched_delete_value,
                CASE
                    WHEN (m.active_element <> p.active_element) THEN m.active_element
                    ELSE NULL::integer
                END AS mismatched_active_value,
                CASE
                    WHEN (m.read_element <> p.read_element) THEN 'read'::text
                    ELSE NULL::text
                END AS mismatched_read,
                CASE
                    WHEN (m.edit_element <> p.edit_element) THEN 'edit'::text
                    ELSE NULL::text
                END AS mismatched_edit,
                CASE
                    WHEN (m.create_element <> p.create_element) THEN 'create'::text
                    ELSE NULL::text
                END AS mismatched_create,
                CASE
                    WHEN (m.delete_element <> p.delete_element) THEN 'delete'::text
                    ELSE NULL::text
                END AS mismatched_delete,
                CASE
                    WHEN (m.active_element <> p.active_element) THEN 'active'::text
                    ELSE NULL::text
                END AS mismatched_active
           FROM ((((public.xdat_field_mapping m
             LEFT JOIN public.xdat_field_mapping_set s ON ((m.xdat_field_mapping_set_xdat_field_mapping_set_id = s.xdat_field_mapping_set_id)))
             LEFT JOIN public.xdat_element_access a ON ((s.permissions_allow_set_xdat_elem_xdat_element_access_id = a.xdat_element_access_id)))
             LEFT JOIN public.xdat_usergroup g ON ((a.xdat_usergroup_xdat_usergroup_id = g.xdat_usergroup_id)))
             LEFT JOIN default_perms p ON ((((g.displayname)::text = p.display_name) AND (p.scope = 'shared'::text))))
          WHERE (((g.displayname)::text = ANY ((ARRAY['Owners'::character varying, 'Members'::character varying, 'Collaborators'::character varying])::text[])) AND ((g.tag)::text IN ( SELECT project_ids.id
                   FROM project_ids)) AND ((m.field)::text ~~ '%/sharing/share/project'::text) AND ((m.field_value)::text <> '*'::text) AND ((m.read_element <> p.read_element) OR (m.edit_element <> p.edit_element) OR (m.create_element <> p.create_element) OR (m.delete_element <> p.delete_element) OR (m.active_element <> p.active_element)))) mismatched;


ALTER TABLE public.project_groups_find_irregular_settings OWNER TO xnat;

