--
-- Name: table_primary_keys_and_sequences; Type: VIEW; Schema: public; Owner: xnat
--

CREATE VIEW public.table_primary_keys_and_sequences AS
 WITH tables_and_key_columns AS (
         SELECT DISTINCT t.table_catalog,
            t.table_schema,
            t.table_name,
            k.column_name,
            cols.data_type,
            c.constraint_type
           FROM (((information_schema.tables t
             LEFT JOIN information_schema.table_constraints c ON (((t.table_name)::name = (c.table_name)::name)))
             LEFT JOIN information_schema.key_column_usage k ON (((c.constraint_name)::name = (k.constraint_name)::name)))
             LEFT JOIN information_schema.columns cols ON ((((t.table_name)::name = (cols.table_name)::name) AND ((k.column_name)::name = (cols.column_name)::name))))
          WHERE (((c.constraint_type)::text = 'PRIMARY KEY'::text) AND ((cols.data_type)::text = ANY ((ARRAY['integer'::character varying, 'bigint'::character varying])::text[])) AND (k.column_name IS NOT NULL))
        ), table_sequences AS (
         WITH all_sequences AS (
                 SELECT get_sequences_and_last_values.sequence_name
                   FROM public.get_sequences_and_last_values() get_sequences_and_last_values(sequence_name, next_seq_value)
                )
         SELECT tab.relname AS table_name,
            seq.relname AS sequence_name
           FROM ((((pg_class seq
             JOIN pg_namespace seq_ns ON ((seq.relnamespace = seq_ns.oid)))
             JOIN pg_depend d ON (((d.objid = seq.oid) AND (d.deptype = 'a'::"char"))))
             JOIN pg_class tab ON (((d.objid = seq.oid) AND (d.refobjid = tab.oid))))
             JOIN pg_namespace tab_ns ON ((tab.relnamespace = tab_ns.oid)))
          WHERE (seq.relname IN ( SELECT all_sequences.sequence_name
                   FROM all_sequences))
          ORDER BY tab.relname, seq.relname
        )
 SELECT pk_tables.table_catalog,
    pk_tables.table_schema,
    pk_tables.table_name,
    pk_tables.column_name,
    seqs.sequence_name
   FROM (( SELECT DISTINCT tables_and_key_columns.table_catalog,
            tables_and_key_columns.table_schema,
            tables_and_key_columns.table_name,
            tables_and_key_columns.column_name,
            tables_and_key_columns.data_type,
            tables_and_key_columns.constraint_type,
            count(tables_and_key_columns.table_name) AS key_count
           FROM tables_and_key_columns
          WHERE ((tables_and_key_columns.constraint_type)::text = 'PRIMARY KEY'::text)
          GROUP BY tables_and_key_columns.table_catalog, tables_and_key_columns.table_schema, tables_and_key_columns.table_name, tables_and_key_columns.column_name, tables_and_key_columns.data_type, tables_and_key_columns.constraint_type) pk_tables
     LEFT JOIN table_sequences seqs ON (((pk_tables.table_name)::name = seqs.table_name)))
  WHERE ((pk_tables.key_count = 1) AND (seqs.sequence_name IS NOT NULL));


ALTER TABLE public.table_primary_keys_and_sequences OWNER TO xnat;

